#include <chrono>

// Node structure for BST
struct Node {
    int data;
    Node* left;
    Node* right;
    Node(int val) : data(val), left(nullptr), right(nullptr) {} // Use nullptr for modern C++
};

// Function to insert into BST
Node* insertIntoBST(Node* root, int data) {
    if (root == nullptr) return new Node(data); // Use nullptr
    if (data < root->data) root->left = insertIntoBST(root->left, data);
    else root->right = insertIntoBST(root->right, data);
    return root;
}

// Selection sort function
void selectionSort(int arr[], int n) {
    for (int i = 0; i < n - 1; ++i) { // Use pre-increment for consistency
        int min_idx = i;
        for (int j = i + 1; j < n; ++j)
            if (arr[j] < arr[min_idx])
                min_idx = j;
        std::swap(arr[i], arr[min_idx]);
    }
}

// Main function
int main() {
    int arr[] = {64, 25, 12, 22, 11};
    const int n = sizeof(arr) / sizeof(arr[0]); // Declare n as const

    // Record start time
    auto start = std::chrono::high_resolution_clock::now();

    // Perform selection sort
    selectionSort(arr, n);

    // Record end time
    auto stop = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration_cast<std::chrono::microseconds>(stop - start);

    // Construct BST from sorted array
    Node* root = nullptr;
    for (int i = 0; i < n; ++i) {
        root = insertIntoBST(root, arr[i]);
    }

    // Print sorted array and duration
    std::cout << "Sorted array: ";
    for (int i = 0; i < n; ++i)
        std::cout << arr[i] << " ";
    std::cout << "\nTime taken by selection sort: "
              << duration.count() << " microseconds" << std::endl;

    return 0;
}
