import codecs

def unpad(padded_text):
    try:
        padded_text.encode('utf-8').decode('utf-8')
    except UnicodeDecodeError:
        raise ValueError("Input contains invalid characters or non-UTF-8 encodings")

    # Check if the input is already a multiple of 16 bytes (no padding needed)
    if len(padded_text) % 16 != 0:
        return padded_text

    # Get the last character to determine the padding length
    padding_length = ord(padded_text[-1])

