   - For example, you can use the following shader to render each vertex as a dot:
     ```csharp
     Shader "Custom/DotShader"
     {
         Properties
         {
             _Color ("Main Color", Color) = (1,1,1,1)
             _MainTex ("Base (RGB)", 2D) = "white" {}
             _Size ("Dot Size", Float) = 0.1
         }
         SubShader
         {
             Tags { "Queue"="Transparent" "IgnoreProjector"="True" "RenderType"="Transparent" }
             LOD 200

             ZWrite Off
             Blend SrcAlpha OneMinusSrcAlpha

             Pass
             {
                 CGPROGRAM
                 #pragma vertex vert
                 #pragma fragment frag

                 struct appdata
                 {
                     float4 vertex : POSITION;
                     float2 uv : TEXCOORD0;
                 };

                 struct v2f
                 {
                     float2 uv : TEXCOORD0;
                     float4 vertex : SV_POSITION;
                 };

                 sampler2D _MainTex;
                 float4 _Color;
                 float _Size;

                 v2f vert (appdata v)
                 {
                     v2f o;
                     o.vertex = UnityObjectToClipPos(v.vertex);
                     o.uv = v.uv;
                     return o;
                 }

                 fixed4 frag (v2f i) : SV_Target
