            {0, 2, 0, 2, 0, -2, 0, 2},
            {0, 0, 2, -2, 0, 0, 2, 2},
            {0, 2, 0, -2, 0, -2, 0, -2},
            {0, 0, 0, 0, -4, 0, 0, 0},
            {0, 2, -2, 0, 0, 2, 2, 0}
        };

        boolean isCorrect = true;
        for (int i = 0; i < 8; i++) {
