```csharp
using SixLabors.ImageSharp;
using SixLabors.ImageSharp.Formats.Jpeg;
using SixLabors.ImageSharp.Formats.Png;
using SixLabors.ImageSharp.Processing;
using System;
using System.IO;

public class ImageProcessor
{
    public static byte[] ConvertAndCompressImage(string imagePath, string outputFormat, int width, int height, int? compressionLevel = null, int? quality = null)
    {
        // Load the image from the specified path
        using (var img = Image.Load(imagePath))
        {
            // Resize the image to the specified dimensions
            img.Mutate(x => x.Resize(width, height));

            // Choose encoder based on the format
            IImageEncoder encoder;
            if (outputFormat.ToLower() == "jpeg")
            {
                encoder = new JpegEncoder { Quality = quality ?? 85 }; // Default quality if none specified
            }
            else if (outputFormat.ToLower() == "png")
            {
                encoder = new PngEncoder { CompressionLevel = compressionLevel ?? 7 }; // Default compression level if none specified
            }
            else
            {
                throw new ArgumentException("Format must be either 'JPEG' or 'PNG'");
            }

            // Save the image to a memory stream and get the byte array
            using (var memoryStream = new MemoryStream())
            {
                img.Save(memoryStream, encoder);
                return memoryStream.ToArray();
            }
        }
    }
}

// Example usage
class Program
{
    static void Main()
    {
        var jpegByteArray = ImageProcessor.ConvertAndCompressImage("path/to/image.jpg", "JPEG", 800, 600, quality: 85);
        var pngByteArray = ImageProcessor.ConvertAndCompressImage("path/to/image.png", "PNG", 800, 600, compressionLevel: 9);

        // Do something with jpegByteArray and pngByteArray...
    }
}
```

### Explanation:
- **Loading the Image**: The image is loaded using `Image.Load` from the `SixLabors.ImageSharp` library.
- **Resizing the Image**: The `Mutate` method is used to apply transformations to the image, such as resizing it to the specified dimensions.
- **Choosing the Encoder**: Depending on the desired output format (`JPEG` or `PNG`), the appropriate encoder is selected. For JPEG, the `Quality` property is set to control the output quality. For PNG, the `CompressionLevel` property is set to control the compression level.
- **Saving the Image**: The image is saved to a `MemoryStream`, and the contents of the stream are then converted to a byte array.

