To ensure the script runs only in the first tab and can programmatically switch tabs and click elements, we need to use a browser extension since userscripts alone cannot achieve these functionalities directly due to security policies. Here’s how you can achieve this using a combined Tampermonkey script and a browser extension approach.

### Tampermonkey Script
```javascript
// ==UserScript==
// @name         DrTorkzadeh Automation Script
// @namespace    http://tampermonkey.net/
// @version      0.4
// @description  Automate certain tasks on DrTorkzadeh website
// @author       You
// @match        http://www.drtorkzadeh.com/
// @grant        none
// ==/UserScript==

(function() {
    'use strict';

    // Function to check if the current window is the first tab
    function isFirstTab() {
        let isFirst = true;
        window.addEventListener('storage', () => {
            isFirst = !window.localStorage.getItem('isFirstTab') === 'true';
        });
        return isFirst;
    }

    // Main logic starts here
    // First step: Check if it's the main page
    if (window.location.pathname !== '/') {
        console.log('Not on the main page.');
        return;
    }

    // Second step: Check the time
    const now = new Date();
    const hour = now.getHours();
    if ((hour >= 22 && hour <= 23) || (hour >= 0 && hour < 3)) {
        console.log('Time is within the range, proceeding.');
    } else {
        console.log('Waiting for the desired time...');
        return; // Wait for the desired time
    }

    // Third step: Check for the specific text and reload the page
    const targetText = "رزرو فقط در ساعات 9 صبح تا 10 صبح امکان پذیر است";
    const foundText = document.body.innerText.includes(targetText);
    if (foundText) {
        console.log('Found the target text, reloading the page...');
        setTimeout(() => {
            location.reload();
        }, 5000); // Wait 5 seconds before reloading
        return;
    }

    // Fourth step: If the text is not found, switch to another tab
    if (isFirstTab()) {
        // Send a message to the browser extension to switch tabs
        chrome.runtime.sendMessage({ action: 'switchToNextTab' }, (response) => {
            console.log(response.message);
            // After switching tabs, the extension should send a message back to the script
            chrome.runtime.sendMessage({ action: 'clickSubmitButton' }, (response) => {
                console.log(response.message);
            });
        });
    } else {
        console.log("This script should run only in the first tab.");
        return;
    }
})();
```

### Browser Extension
Create a simple browser extension that includes a background script to handle the tab switching and element clicking. The extension will listen for messages from the Tampermonkey script and perform the required actions.

**manifest.json**
```json
{
  "manifest_version": 2,
  "name": "DrTorkzadeh Automation Extension",
  "version": "1.0",
  "background": {
    "scripts": ["background.js"]
  },
  "permissions": [
    "tabs",
    "activeTab"
  ],
  "description": "Enables automation for DrTorkzadeh website"
}
```

**background.js**
```javascript
chrome.runtime.onMessage.addListener((request, sender, sendResponse) => {
    if (request.action === 'switchToNextTab') {
        chrome.tabs.query({ currentWindow: true }, (tabs) => {
            let currentIndex = tabs.indexOf(sender.tab);
            if (currentIndex < tabs.length - 1) {
                chrome.tabs.update(tabs[currentIndex + 1].id, { active: true }, () => {
                    sendResponse({ message: 'Switched to next tab.' });
                });
            } else {
                sendResponse({ message: 'No next tab available.' });
            }
        });
        return true; // Keep the message channel open
    } else if (request.action === 'clickSubmitButton') {
        // Send a message to the content script in the current tab to click the element
        chrome.tabs.query({ active: true, currentWindow: true }, (tabs) => {
            chrome.tabs.sendMessage(tabs[0].id, { action: 'clickSubmitButton' }, (response) => {
                console.log(response.message);
                sendResponse({ message: 'Clicked the submit button.' });
            });
        });
        return true; // Keep the message channel open
    }
});

chrome.tabs.onUpdated.addListener((tabId, changeInfo, tab) => {
    if (changeInfo.status === 'complete' && tab.url.includes('http://www.drtorkzadeh.com/')) {
        // Check if this is the first tab
        chrome.tabs.query({}, (tabs) => {
            if (tabs.indexOf(tab) === 0) {
                chrome.tabs.executeScript(tabId, { file: 'content.js' }, () => {
                    chrome.storage.local.set({ isFirstTab: true }, () => {
                        console.log('First tab identified.');
                    });
                });
            }
        });
    }
});
```

**content.js**
```javascript
chrome.runtime.onMessage.addListener((request, sender, sendResponse) => {
    if (request.action === 'clickSubmitButton') {
        const submitButton = document.querySelector('#submit');
        if (submitButton) {
            submitButton.click();
            sendResponse({ message: 'Clicked the submit button.' });
        } else {
            sendResponse({ message: 'Submit button not found.' });
        }
        return true; // Keep the message channel open
    }
});
```

This setup ensures that the script runs only in the first tab and allows for programmatically switching tabs and clicking elements as required. Note that the extension needs to be installed and enabled for these functionalities to work.

