    const handleTouch = (event) => {
        const { nativeEvent: { locationX, locationY } } = event;
        setUserPath((prevPath) => `${prevPath} L ${locationX},${locationY}`);
    }

    if (loading) {
        return (
            <View style={styles.loadingContainer}> 
                <ActivityIndicator size="large" color="#00ff00" /> 
            </View>
        );
    }

    return (
        <View style={styles.container}> 
            <Svg onTouchMove={handleTouch}> 
                <Path d={`M${userPath}`} stroke="blue" strokeWidth="2" fill="none" /> 
            </Svg> 
            <Text>Data fetched successfully:</Text> 
            <Text>{JSON.stringify(data)}</Text> 
        </View>
    );
};

const styles = StyleSheet.create({ 
    container: { 
        flex: 1, 
        justifyContent: 'center', 
        alignItems: 'center', 
    }, 
