To solve the trust region problem and visualize the solutions in MATLAB, we will use the `fmincon` function to find the minimum of the quadratic model m_k(p) subject to the constraint ||p|| ≤ Δ_k. The code below updates the existing MATLAB script to include the trust region problem solution and clearly show the family of solutions for varying trust region radii.

```matlab
function trustRegionPlot()
    % Define the function f(x)
    f = @(x) 10*(x(2) - x(1)^2)^2 + (1 - x(1))^2;

    % Compute the gradient of f(x)
    grad_f = @(x) [-40*x(1)*(x(2) - x(1)^2) - 2*(1 - x(1)); 20*(x(2) - x(1)^2)];

    % Compute the Hessian of f(x)
    hessian_f = @(x) [120*x(1)^2 - 40*x(2) + 2, -40*x(1); -40*x(1), 20];

    % Points of interest
    x1 = [0; -1];
    x2 = [0; 0.5];

    % Trust region radii
    delta_values = linspace(0, 2, 10);

    % Plot contours for each point
    figure;
    subplot(1, 2, 1);
    hold on;
    title('Contours at x = [0; -1]');
    for delta = delta_values
        plotTrustRegion(f, grad_f, hessian_f, x1, delta);
    end

    subplot(1, 2, 2);
    hold on;
    title('Contours at x = [0; 0.5]');
    for delta = delta_values
        plotTrustRegion(f, grad_f, hessian_f, x2, delta);
    end
end

function plotTrustRegion(f, grad_f, hessian_f, x, delta)
    % Quadratic model
    mk = @(p) f(x) + grad_f(x)' * p + 0.5 * p' * hessian_f(x) * p;

    % Grid for plotting
    [X, Y] = meshgrid(-2:0.1:2, -2:0.1:2);
    Z = zeros(size(X));
    for i = 1:numel(X)
        p = [X(i); Y(i)] - x;
        Z(i) = mk(p);
    end

    % Contour plot
    contour(X, Y, reshape(Z, size(X)), 'ShowText', 'on');

    % Trust region circle
    theta = linspace(0, 2*pi, 100);
    circle_x = x(1) + delta * cos(theta);
    circle_y = x(2) + delta * sin(theta);
    plot(circle_x, circle_y, 'r');

    % Solve the trust region problem
    options = optimoptions('fmincon','Algorithm','interior-point');
    p0 = zeros(2, 1);
    nonlinearConstraints = @(p) delta^2 - norm(p)^2;
    [p, ~, exitflag] = fmincon(@(p) mk(p), p0, [], [], [], [], [], [], ...
        @(p)deal([], [], nonlinearConstraints(p)), options);

    % Plot the solution
    if exitflag > 0
        plot(p(1) + x(1), p(2) + x(2), 'ro');
    else
        warning('Optimization did not converge properly.');
    end
end
```

