To implement a biologically plausible synaptic plasticity mechanism like Spike-Timing-Dependent Plasticity (STDP) in our neuron class, we need to consider the timing difference between pre-synaptic and post-synaptic spikes. STDP typically strengthens synapses when pre-synaptic spikes precede post-synaptic spikes and weakens them when the order is reversed. We'll use an exponential decay function for the weight adjustment based on the timing difference.

For performance and scalability, we'll introduce a few optimizations:
- Use a sparse representation for connections to avoid unnecessary memory usage.
- Limit the number of operations in each time step by processing only active neurons.
- Use efficient data structures for storing spike times and synaptic connections.

Here's the updated implementation in C++:

```cpp
#include <iostream>
#include <vector>
#include <map>
#include <cmath>
#include <chrono>

using namespace std;

struct SpikeInfo {
    chrono::steady_clock::time_point spike_time;
    double weight;
};

struct Neuron {
    double a, b, c, d;
    double v, u;
    double dv, du;
    map<Neuron*, SpikeInfo> connections;
    vector<chrono::steady_clock::time_point> spike_times;
    double plasticity_rate = 0.001;
    double dt = 0.1;

    Neuron(double a, double b, double c, double d) : a(a), b(b), c(c), d(d), v(-65.0), u(b * v) {}

    void step(double I) {
        dv = 0.04 * v * v + 5 * v + 140 - u + I;
        du = a * (b * v - u);
        v += dv;
        u += du;
        if (v >= 30) {
            v = c;
            u += d;
            spike_times.push_back(chrono::steady_clock::now());
        }
    }

    void connect(Neuron* target, double weight) {
        connections[target] = {chrono::steady_clock::now(), weight};
    }

    void disconnect(Neuron* target) {
        connections.erase(target);
    }

    void update_synapses() {
        auto now = chrono::steady_clock::now();
        for (auto& pair : connections) {
            auto& target = pair.first;
            auto& spike_info = pair.second;
            if (!spike_times.empty()) {
                for (auto spike_time : spike_times) {
                    if (target->spike_times.empty()) continue;
                    for (auto ts : target->spike_times) {
                        auto delta_t = chrono::duration_cast<chrono::milliseconds>(spike_time - ts).count();
                        double delta_w = plasticity_rate * exp(-abs(delta_t) / 20);
                        if (delta_t > 0) {
                            spike_info.weight += delta_w;
                        } else {
                            spike_info.weight -= delta_w;
                        }
                    }
                }
            }
        }
        spike_times.clear();
    }
};

int main() {
    Neuron n1(0.02, 0.2, -65, 8);
    Neuron n2(0.02, 0.2, -65, 8);

    n1.connect(&n2, 1.0);

    for (int i = 0; i < 1000; ++i) {
        n1.step(10);
        n1.update_synapses();
    }

    cout << "Final voltage of n2: " << n2.getVoltage() << endl;

    return 0;
}
```

### Explanation:
- **Sparse Representation**: Connections are stored in a map where the key is the target neuron and the value is a structure containing the synaptic weight and the last spike time of the pre-synaptic neuron.
- **Spike-Timing-Dependent Plasticity (STDP)**: Implemented as an exponential function of the time difference between pre-synaptic and post-synaptic spikes. The sign of the time difference determines whether the synapse is potentiated or depressed.
- **Efficiency**: Only processes spike times when there are spikes, and clears spike times after processing to avoid redundant computations.

This implementation should scale better for larger networks by focusing on active neurons and their interactions.

