```javascript
const svg = d3.select('body').append('svg')
            .attr('width', window.innerWidth)
            .attr('height', window.innerHeight);

// Function to draw the sun
function drawSun() {
    svg.append('circle')
       .attr('cx', window.innerWidth / 2)
       .attr('cy', window.innerHeight / 2)
       .attr('r', 50)
       .attr('fill', 'yellow');
}

// Function to draw a planet
function drawPlanet(radius, orbitRadius, color) {
    const angle = Date.now() / 1000; // Time-based angle for animation
    const x = window.innerWidth / 2 + orbitRadius * Math.cos(angle);
    const y = window.innerHeight / 2 + orbitRadius * Math.sin(angle);
    svg.append('circle')
       .attr('cx', x)
       .attr('cy', y)
       .attr('r', radius)
       .attr('fill', color);
}

// Call the functions to draw the sun and planets
setInterval(() => {
    svg.selectAll('*').remove(); // Clear the svg each frame
    drawSun();
    drawPlanet(10, 200, 'blue'); // Earth
    drawPlanet(8, 250, 'red'); // Mars
}, 10); // Refresh rate per second
```

This setup initializes an SVG element and uses D3.js to create circles representing the planets. The `setInterval` function updates the positions of the planets based on their orbits, creating a dynamic visualization.

